const TYPES = {
  say: {},
  // 🛂 签证官问答（2026-11-11，样板 样板/签证面试多说样板.html，用户：「可以，放进软件」）：D.iv = 一天 4–5 个真实常问的问题，D.iv.mock = 第 7 天真的一场
  iv: {lock: 1, h: () => `<div class="acx-iv" data-iv></div>`, w: c => ivRun(c)},
  // 🧱 拼你自己的话（进阶活动，2026-11-10，样板 样板/进阶活动玩一遍样板.html，用户：「对，放进软件」）
  // 一步接一步：先听一个人（字是模糊的）→ 他什么态度 → 抓住转弯的那个词 → 选职业（聊工作）→ 从几种说法里选最像你的 → 跟前几天的话连成一段 → 下面说三遍
  // 数据（最后一天 all: true = 前几天的话 + 今天这句连成一整段说）D.b = {hear: [人, 中文, 英文], ask: [英文, 中文], ao: [[英文, 对不对, 中文], …], turn: {s: "…＿…", o: [[词, 对不对, 英文说明], …], ex: [中文, 英文]},
  //            pre, suf, mine: [[中文, 英文], …] 或 jobs: {职业: {n: [中文, 英文], mine: […]}}, all: true（最后一天：整段）}
  build: {lock: 1, h: (D, d, J, a) => { const B = D.b || {}, past = paraOf(a, J, d), jb = jobOf(B);
    let n = 0; const sec = (_, html) => `<div class="acx-bs" data-bs="${n++}"${n > 1 ? " hidden" : ""}>${html}</div>`;
    return `<div class="acx-tk">🧱 ${B.all ? T("把这几天的话连成一段", "Put your days together") : T("拼你自己的话", "Build your own line")}</div>
     ${B.hear ? sec(1, `<div class="acx-bh"><button class="acx-bp" data-bplay>▶</button><div><div class="acx-btx blur" data-btx>${esc(B.hear[1])}</div><small>${esc(who(B.hear[0]).nm)}${who(B.hear[0]).home ? " · " + esc(who(B.hear[0]).home) : ""}</small></div></div>
       <div class="acx-q">${esc(T(B.ask[1] || B.ask[0], B.ask[0]))}</div><div class="acx-opts" data-bask>${B.ao.map((o, k) => `<button class="acx-opt" data-k="${k}">${esc(T(o[2] || o[0], o[0]))}</button>`).join("")}</div><div class="acx-note" data-bnote></div>`) : ""}
     ${B.turn ? sec(1, `<div class="acx-q big">${esc(B.turn.s).replace("＿", '<span class="acx-bgap">？</span>')}</div><div class="acx-tk2">${T("哪个词让这句话「转」回来？", "Which word makes the turn?")}</div>
       <div class="acx-opts" data-bturn>${B.turn.o.map((o, k) => `<button class="acx-opt acx-zhb" data-k="${k}">${esc(o[0])}</button>`).join("")}</div><div class="acx-note" data-bnote></div>`) : ""}
     ${B.jobs ? sec(1, `<div class="acx-tk2">${T("你是做什么的？", "What do you do?")}</div><div class="acx-chips" data-bjobs>${Object.entries(B.jobs).map(([k, v]) => `<button class="acx-chip${jb === k ? " on" : ""}" data-k="${esc(k)}">${esc(v.n[0])} <small>${esc(TR(v.n[1]))}</small></button>`).join("")}</div>`) : ""}
     ${sec(1, `<div class="acx-tk2">${esc(T(B.pick ? B.pick[1] : "哪句最像你想说的？", B.pick ? B.pick[0] : "Which is closest to what you'd say?"))}</div><div class="acx-bmine" data-bmine>${mineHtml(B, jb)}</div>`)}
     ${sec(1, `<div class="acx-tk2">${T("你的这一段", "Your paragraph")}</div><div class="acx-bpara" data-bpara>${past.map(t => `<span class="old">${esc(t)}</span>`).join("")}${`<span class="acx-bgap2">${esc(B.pre || "")}……</span>`}</div>`)}`; },
    w: c => { const B = c.D.b || {}, $ = c.$, a = c.a, past = paraOf(a, ST().j[a.id], c.d); let heard = false;
      const next = el => { const box = el.closest("[data-bs]"), nx = box && c.pg.querySelector('[data-bs="' + (+box.dataset.bs + 1) + '"]'); if (nx && nx.hidden){ nx.hidden = false; setTimeout(() => nx.scrollIntoView({behavior: "smooth", block: "center"}), 150); } };
      const setLine = t => { c.setOwn(B.all ? past.join("") + t : t); const P = $("[data-bpara]"); if (P) P.innerHTML = past.map(x => `<span class="old">${esc(x)}</span>`).join("") + `<span class="new">${esc(t)}</span>`; c.unlock(); };
      const pb = $("[data-bplay]"); if (pb) pb.onclick = () => { heard = true; playSay(B.hear[1], "zh-CN", .9); };
      const ask = $("[data-bask]"); if (ask) ask.querySelectorAll("button").forEach(b => b.onclick = () => { const o = B.ao[+b.dataset.k], nt = b.closest("[data-bs]").querySelector("[data-bnote]");
        if (!heard){ buddy(a, "listen1"); blip("soft"); return; }
        if (o[1]){ b.classList.add("ok"); $("[data-btx]").classList.remove("blur"); nt.className = "acx-note ok"; nt.textContent = B.hear[2] ? TR(B.hear[2]) : ""; buddy(a, "qok"); blip("ok"); sparks(b, 10); next(b); }
        else { b.classList.add("no"); buddy(a, "listen2"); blip("soft"); } });
      const tu = $("[data-bturn]"); if (tu) tu.querySelectorAll("button").forEach(b => b.onclick = () => { const o = B.turn.o[+b.dataset.k], nt = b.closest("[data-bs]").querySelector("[data-bnote]");
        if (o[1]){ b.classList.add("ok"); const g = b.closest("[data-bs]").querySelector(".acx-bgap"); if (g){ g.textContent = o[0]; g.classList.add("on"); } nt.className = "acx-note ok"; nt.innerHTML = `<b class="acx-zhb">${esc(B.turn.ex[0])}</b> = ${esc(TR(B.turn.ex[1]))}`; buddy(a, "qok"); blip("ok"); sparks(b, 10); next(b); }
        else { b.classList.add("no"); nt.className = "acx-note"; nt.textContent = TR(o[2] || ""); blip("soft"); } });
      const wireMine = () => c.pg.querySelectorAll("[data-bmine] button").forEach(b => b.onclick = () => { c.pg.querySelectorAll("[data-bmine] button").forEach(x => x.classList.remove("on")); b.classList.add("on");
        setLine((B.pre || "") + b.dataset.t + (B.suf || "")); buddy(a, "mine"); blip("ok"); next(b); });
      const jbs = $("[data-bjobs]"); if (jbs) jbs.querySelectorAll("button").forEach(b => b.onclick = () => { const o = ST(); o.job = b.dataset.k; SAVE(o); jbs.querySelectorAll("button").forEach(x => x.classList.toggle("on", x === b));
        const m = $("[data-bmine]"); if (m){ m.innerHTML = mineHtml(B, b.dataset.k); wireMine(); } blip("ok"); next(b); });
      wireMine();
      if (B.jobs && jobOf(B) && jbs) next(jbs);
      const own = $(".acx-own"); if (own && own.value) { const P = $("[data-bpara]"); if (P && !B.all) P.innerHTML = past.map(x => `<span class="old">${esc(x)}</span>`).join("") + `<span class="new">${esc(own.value)}</span>`; c.pg.querySelectorAll("[data-bs]").forEach(x => x.hidden = false); c.unlock(); } }},
  follow: {lock: 1, h: D => `<div class="acx-tk">🏃 ${T("跟着做", "Follow along")} · ${(D.moves || []).length} ${T("个动作", "moves")}</div>
    <div class="acx-fl"><div class="acx-fc"><b data-fen>${en1(D.moves[0])}</b><small data-fzh>${ZH() ? esc(D.moves[0][1]) : ""}</small><div class="acx-fbar"><i data-fbar></i></div><span data-fn>1 / ${D.moves.length}</span></div>
    <div class="acx-fls">${D.moves.map((m, i) => `<span data-fi="${i}">${esc(m[0])}</span>`).join("")}</div><button class="acx-btn say" data-fgo>▶ ${T("开始，跟着做", "Start")}</button></div>`,
    w: c => { const M = c.D.moves, b = c.$("[data-fgo]"); let i = 0, tm = null;
      const show = k => { c.$("[data-fen]").textContent = M[k][0]; c.$("[data-fzh]").textContent = ZH() ? M[k][1] || "" : ""; c.$("[data-fn]").textContent = (k + 1) + " / " + M.length; c.pg.querySelectorAll("[data-fi]").forEach((s, j) => s.className = j < k ? "d" : j === k ? "t" : ""); };
      const step = () => { if (i >= M.length){ c.pg.querySelectorAll("[data-fi]").forEach(s => s.className = "d"); b.textContent = "✓ " + T("做完了，现在说出来 ↓", "Done — now say it ↓"); c.unlock(); return; }
        show(i); speak(M[i][0], c.lang); const s = (M[i][2] || 8) * 1000, bar = c.$("[data-fbar]"); bar.style.transition = "none"; bar.style.width = "0"; requestAnimationFrame(() => { bar.style.transition = "width " + s + "ms linear"; bar.style.width = "100%"; });
        tm = setTimeout(() => { i++; step(); }, s); };
      b.onclick = () => { if (tm) return; b.textContent = T("跟着做…", "Going…"); step(); }; }},
  photo: {lock: 1, h: D => `<div class="acx-tk">📷 ${T("拍一张", "Take a photo")}</div><div class="acx-q">${en1(D.prompt)}</div>${zh2(D.prompt)}
    <div class="acx-ph"><label class="acx-btn say">📷 ${T("拍照 / 选一张", "Take or pick one")}<input type="file" accept="image/*" capture="environment" hidden data-phin></label><a data-phskip>${T("这次不拍", "Skip the photo")}</a></div><img class="acx-phv" data-phv hidden alt="">`,
    w: c => { const f = c.$("[data-phin]"), v = c.$("[data-phv]");
      f.onchange = () => { const x = f.files && f.files[0]; if (!x) return; v.src = URL.createObjectURL(x); v.hidden = false; c.unlock(); };
      c.$("[data-phskip]").onclick = () => c.unlock(); }},
  plan: {lock: 1, h: D => `<div class="acx-tk">🧺 ${T("排一排", "Make your plan")}</div>${(D.slots || []).map((s, i) => `<div class="acx-sl"><b>${en1(s.lab)}</b>${zh2(s.lab)}<div class="acx-chips">${(s.opts || []).map(o => `<button class="acx-chip" data-sl="${i}" data-v="${esc(o)}">${esc(o)}</button>`).join("")}<input class="acx-slin" data-slin="${i}" placeholder="${T("或者自己写", "or write your own")}"></div></div>`).join("")}
    <div class="acx-built" data-built>${esc(D.tpl || "").replace(/\{\d\}/g, "___")}</div>`,
    w: c => { const D = c.D, V = [], N = (D.slots || []).length;
      const upd = () => { const s = (D.tpl || "").replace(/\{(\d)\}/g, (_, k) => V[k] || "___"); c.$("[data-built]").textContent = s; if (V.filter(Boolean).length >= N){ c.setOwn(s); c.unlock(); } };
      c.pg.querySelectorAll("[data-sl]").forEach(b => b.onclick = () => { const k = +b.dataset.sl; V[k] = b.dataset.v; c.pg.querySelectorAll('[data-sl="' + k + '"]').forEach(x => x.classList.toggle("on", x === b)); upd(); });
      c.pg.querySelectorAll("[data-slin]").forEach(n => n.oninput = () => { const k = +n.dataset.slin; V[k] = n.value.trim(); c.pg.querySelectorAll('[data-sl="' + k + '"]').forEach(x => x.classList.remove("on")); upd(); }); }},
  walk: {lock: 1, h: D => `<div class="acx-tk">🚶 ${T("走一遍", "Walk it")} · ${(D.stops || []).length} ${T("站", "stops")}</div><div data-wk></div>`,
    w: c => { const S = c.D.stops || [], box = c.$("[data-wk]"); let i = 0;
      const show = () => { if (i >= S.length){ box.innerHTML = `<div class="acx-ok">✓ ${T("走完了。现在把这一路最有用的一句说出来 ↓", "Done. Now say the most useful line ↓")}</div>`; c.unlock(); return; }
        const s = S[i]; box.innerHTML = `<div class="acx-wst">${s.img ? `<img src="${esc(imgU(s.img))}" alt="">` : ""}<div><span class="acx-tag">${i + 1} / ${S.length} · 📍 ${en1(s.at)}${ZH() && s.at[1] ? " · " + esc(s.at[1]) : ""}</span><div class="acx-q">${en1(s.q)}</div>${zh2(s.q)}</div></div>
          <div class="acx-opts">${s.opts.map((o, k) => `<button class="acx-opt" data-o="${k}">${esc(o[0])}</button>`).join("")}</div><div class="acx-note" data-note></div>`;
        box.querySelectorAll("[data-o]").forEach(b => b.onclick = () => { const o = s.opts[+b.dataset.o], n = box.querySelector("[data-note]");
          if (o[1]){ b.classList.add("ok"); speak(o[0], c.lang); n.className = "acx-note ok"; n.innerHTML = esc(o[2] || "") + ` <button class="acx-btn lt" data-nx>${i + 1 < S.length ? T("下一站 →", "Next stop →") : T("走完了 ✓", "Done ✓")}</button>`; box.querySelector("[data-nx]").onclick = () => { i++; show(); }; }
          else { b.classList.add("no"); n.className = "acx-note"; n.textContent = (o[2] || T("这样说有点怪，换一个试试", "That sounds a bit odd — try another")); } }); };
      show(); }},
  vote: {lock: 1, h: D => `<div class="acx-tk">⚖️ ${T("站一边", "Pick a side")}</div><div class="acx-q big">${en1(D.q)}</div>${zh2(D.q)}
    <div class="acx-sides">${(D.sides || []).map((s, k) => `<button class="acx-side" data-sd="${k}"><b>${esc(s[0])}</b>${ZH() && s[1] ? `<small>${esc(s[1])}</small>` : ""}<i style="width:0"></i><em></em></button>`).join("")}</div>`,
    w: c => { const S = c.D.sides || [];
      c.pg.querySelectorAll("[data-sd]").forEach(b => b.onclick = () => { const k = +b.dataset.sd;
        c.pg.querySelectorAll("[data-sd]").forEach((x, j) => { x.classList.toggle("on", j === k); x.querySelector("i").style.width = (S[j][2] || 0) + "%"; x.querySelector("em").textContent = (S[j][2] || 0) + "%"; });
        c.setOwn(plain(c.D.line || "").replace("___", /^I\b/.test(S[k][0]) ? S[k][0] : S[k][0].charAt(0).toLowerCase() + S[k][0].slice(1)), true); c.unlock(); }); }},
  listen: {lock: 1, h: D => `<div class="acx-tk">🎧 ${T("听，听到就点", "Listen — tap what you hear")}</div><button class="acx-btn say" data-lplay>🔊 ${T("放一遍", "Play")}</button>
    <div class="acx-chips lis">${(D.chips || []).map((w, k) => `<button class="acx-chip" data-ch="${k}">${esc(w[0])}</button>`).join("")}</div><div class="acx-note" data-lnote></div>
    <div class="acx-script" data-lscr hidden>${esc(D.text || "")}</div><a class="acx-lnk" data-lshow>${T("看原文", "Show the words")}</a>`,
    w: c => { const D = c.D, C = D.chips || [], need = C.filter(x => x[1]).length; let got = 0;
      c.$("[data-lplay]").onclick = () => speak(D.text, c.lang);
      const done = () => { c.$("[data-lscr]").hidden = false; c.unlock(); };
      c.pg.querySelectorAll("[data-ch]").forEach(b => b.onclick = () => { const w = C[+b.dataset.ch], n = c.$("[data-lnote]"); if (b.classList.contains("ok")) return;
        if (w[1]){ b.classList.add("ok"); got++; n.textContent = got >= need ? "✓ " + T("都抓到了", "Got them all") : T("抓到 " + got + " / " + need, got + " / " + need); if (got >= need) done(); }
        else { b.classList.add("no"); n.textContent = T("这一段里没有它", "That one isn't in there"); } });
      c.$("[data-lshow]").onclick = done; }},
  look: {lock: 1, h: D => `<div class="acx-tk">👀 ${T("看", "Look")} ${D.secs || 60} ${T("秒", "seconds")}</div><div class="acx-q">${en1(D.q)}</div>${zh2(D.q)}
    <div class="acx-look"><img src="${esc(imgU(D.img))}" alt=""><div class="acx-fbar"><i data-lbar></i></div></div><button class="acx-btn say" data-lk>▶ ${T("开始看", "Start looking")}</button>`,
    w: c => { const b = c.$("[data-lk]"), s = (c.D.secs || 60) * 1000, bar = c.$("[data-lbar]"); let on = 0;
      b.onclick = () => { if (on){ c.unlock(); b.textContent = "✓"; return; } on = 1; b.textContent = T("看好了 →", "I've looked →"); bar.style.transition = "width " + s + "ms linear"; requestAnimationFrame(() => bar.style.width = "100%"); setTimeout(() => { b.textContent = "✓ " + T("时间到，说你看到了什么 ↓", "Time — say what you saw ↓"); c.unlock(); }, s); }; }},
  guess: {lock: 1, h: D => `<div class="acx-tk">🤔 ${T("猜一猜", "Guess")}</div>${D.img ? `<img class="acx-gimg" src="${esc(imgU(D.img))}" alt="">` : ""}<div class="acx-q big">${en1(D.q)}</div>${zh2(D.q)}
    <div class="acx-opts">${(D.opts || []).map((o, k) => `<button class="acx-opt" data-g="${k}">${esc(o[0])}</button>`).join("")}</div><div class="acx-note" data-gn></div>`,
    w: c => { const D = c.D; c.pg.querySelectorAll("[data-g]").forEach(b => b.onclick = () => { const o = D.opts[+b.dataset.g], n = c.$("[data-gn]");
      if (o[1]){ b.classList.add("ok"); n.className = "acx-note ok"; n.innerHTML = en1(D.reveal) + zh2(D.reveal); c.unlock(); } else { b.classList.add("no"); n.className = "acx-note"; n.textContent = T("不是这个，再猜一个", "Not this one — guess again"); } }); }},
  together: {h: (D, d, J) => `<div class="acx-tk">🧩 ${T("一起做", "Make it together")} · ${en1(D.title)}</div>${zh2(D.title)}
    <div class="acx-wall">${(D.wall || []).map(w => `<div class="acx-wc" data-say="${esc(w[1])}" data-lang="${esc(who(w[0]).lang || "en-US")}">${av(w[0], 26)}<div>${esc(w[1])}${ZH() && w[2] ? `<small>${esc(w[2])}</small>` : ""}</div></div>`).join("")}
    <div class="acx-wc you" data-wyou>${J && (J.done || {})[d] ? esc(J.done[d]) : T("你的这一张 · 写好、说出来就贴上", "Your piece — write it, say it, it goes up")}</div></div>`,
    w: c => { c.onDone = t => { const y = c.$("[data-wyou]"); if (y){ y.textContent = t; y.classList.add("on"); } }; }},
  timed: {h: (D, d, J) => `<div class="acx-tk">⏱️ ${D.secs || 60} ${T("秒，一直说", "seconds — keep talking")}</div><div class="acx-q big">${en1(D.prompt)}</div>${zh2(D.prompt)}
    ${(D.hints || []).length ? `<div class="acx-chips">${D.hints.map(h => `<span class="acx-chip st">${esc(h)}</span>`).join("")}</div>` : ""}
    <div class="acx-row2"><button class="acx-ring" data-tgo><b data-tn>${D.secs || 60}</b><small>${T("开始", "Start")}</small></button><div class="acx-heard" data-th style="flex:1"></div></div>
    <div class="acx-mine${J && (J.done || {})[d] != null ? " on" : ""}">✓ ${T("说完了。", "Done.")}</div>`,
    w: c => { const b = c.$("[data-tgo]"), n = c.$("[data-tn]"), h = c.$("[data-th]"), S = c.D.secs || 60; let on = 0;
      b.onclick = () => { if (on) return; on = 1; b.classList.add("rec"); b.querySelector("small").textContent = T("在听", "Listening"); let left = S, txt = "", r = null;
        const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
        if (SR){ try { r = new SR(); r.lang = "en-US"; r.continuous = true; r.interimResults = true; r.onresult = ev => { txt = [...ev.results].map(q => q[0].transcript).join(" "); h.textContent = "“" + txt + "”"; }; r.onend = () => { if (left > 0) try { r.start(); } catch(e){} }; r.start(); } catch(e){ r = null; } }
        const iv = setInterval(() => { left--; n.textContent = left; if (left <= 0){ clearInterval(iv); on = 0; b.classList.remove("rec"); b.querySelector("small").textContent = T("再来", "Again"); try { r && r.stop(); } catch(e){}
          c.finish(txt.trim()); } }, 1000); }; }},
  diary: {h: (D, d, J, a) => { const past = a.D.map((x, i) => [i, J && (J.done || {})[i]]).filter(x => x[1] && x[0] !== d);
    return `<div class="acx-tk">📔 ${T("今天的一页", "Today's page")}</div><div class="acx-q big">${en1(D.q)}</div>${zh2(D.q)}
    ${past.length ? `<div class="acx-diary">${past.map(([i, t]) => `<div><b>${T("第 " + (i + 1) + " 天", "Day " + (i + 1))}</b>${esc(t)}</div>`).join("")}</div>` : `<div class="acx-note">${T("这是第一页。以后每天写一句，这里会一页页攒起来。", "First page. One line a day, and they pile up here.")}</div>`}`; }}
};
// ── 🛂 签证官问答（TYPES.iv）──
// 每题：对方随机用一种说法问（点了再念，下面列别的说法）→ 按档回答（刚开始：要用的词 + 完整回答 · 能聊日常：开头 + 思路 · 比较流利：只有问题）→ 说一遍就进下一题；
// 全答完把今天的回答连成一段说一遍 = 这一天完成（说自己的那天问完接「说你自己的」那一句）。上次答过题、今天第一次打开：先复习，换一种说法再问 3 个。
// 学英语：签证（D.iv 写在活动 json 里）；学中文的人（2026-11-11）：中文/iv/<活动>.json → window.ACTS_IV_ZH，mode() 挂到 D.iv 上，对方是 who（店员、路人……），中文自动配拼音（template2 的 pyWrap），声音和识别用 zh-CN。
// 中文题的字段：v = [[中文, 拼音]…]、s = [中文, 拼音]、ideas = [[中文, 拼音]…]、w = [[中文, 拼音, 英文]…]、z / az 是英文意思；英语题 v、ideas 是字符串，w = [英文, 中文]。
// solo: true 的题不放进「连起来」那一段（跟同一天别的回答连着读会矛盾，比如「带了护照」和「回去拿原件」）。
// 存在 act.v1：ivlv = 选的档（a / b / c）；j[id].ivh = {"天|题": [用过的问法序号]}（第 7 天偶尔出的那题是 "r|题"），ivt = 最后答题那天，rv = 复习过的那天
const IVLV = [["a", "刚开始", "Just starting"], ["b", "能聊日常", "Everyday chat"], ["c", "比较流利", "Fairly fluent"]];
const ivTx = v => Array.isArray(v) ? v[0] : v || "";
const ivAll = x => [x.q].concat((x.v || []).map(ivTx));
const ivGet = (a, key) => { const [d, k] = String(key).split("|"); if (d === "r"){ const m = (a.D.find(D => D.iv && D.iv.mock) || {}).iv || {}; return (m.rare || [])[+k]; } const iv = (a.D[+d] || {}).iv; return Array.isArray(iv) ? iv[+k] : null; };
const shuf = A => { A = A.slice(); for (let i = A.length - 1; i > 0; i--){ const j = Math.floor(Math.random() * (i + 1)); [A[i], A[j]] = [A[j], A[i]]; } return A; };
function ivList(a, d){ const iv = a.D[d].iv; if (Array.isArray(iv)) return iv.map((_, k) => d + "|" + k);
  const L = (iv.fixed || []).map(x => x.join("|")).concat(shuf(iv.pick || []).slice(0, iv.n || 3).map(x => x.join("|")));   // 真的一场：先按真实顺序，再随机抽几题，偶尔一题少见的
  if ((iv.rare || []).length && Math.random() < .2) L.push("r|" + Math.floor(Math.random() * iv.rare.length));
  return L.filter(k => ivGet(a, k)); }
function ivPick(x, used, review){ let ok = [...Array(ivAll(x).length).keys()]; const U = used || [];   // 复习：一定不用上次那种问法
  if (review){ const r = ok.filter(i => !U.includes(i)); ok = r.length ? r : ok.filter(i => i !== U[U.length - 1]); if (!ok.length) ok = [0]; }
  return ok[Math.floor(Math.random() * ok.length)]; }
// 对方的声音：英语 = 签证官（gen_act_voices.py 配的美国口音），中文 = 一个固定的店员 / 路人声音；没配到就手机朗读。都不是主持人的声音
